"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-slider";
export const sliderVariants = cva(
  "v-slider [-webkit-appearance:none] [appearance:none] [width:100%] [height:10px] [border-radius:var(--r-pill)] [background:var(--v-beige)] [outline-offset:6px] [cursor:pointer] relative flex items-center touch-none select-none",
  {
    variants: { variant: { default: "", pink: "-pink" } },
    defaultVariants: { variant: "default" },
  },
);
export type SliderProps = React.ComponentProps<typeof Primitive.Root> &
  VariantProps<typeof sliderVariants> & {
    thumbLabel?: string | ((index: number) => string);
  };
export function Slider({
  className,
  variant,
  value,
  defaultValue = [50],
  min = 0,
  max = 100,
  thumbLabel,
  onValueChange,
  style,
  ...props
}: SliderProps) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue);
  const values = value ?? uncontrolledValue;
  const percent = max > min ? Math.min(100, Math.max(0, ((values[0] ?? min) - min) / (max - min) * 100)) : 0;
  const range = values.length > 1 || props.orientation === "vertical";
  const handleValueChange = (next: number[]) => {
    if (value === undefined) setUncontrolledValue(next);
    onValueChange?.(next);
  };
  return (
    <Primitive.Root
      data-slot="slider"
      data-part="track"
      data-range={range || undefined}
      className={cn(sliderVariants({ variant }), className)}
      value={value}
      defaultValue={defaultValue}
      min={min}
      max={max}
      onValueChange={handleValueChange}
      style={{ "--p": `${percent}%`, ...style } as React.CSSProperties}
      {...props}
    >
      <Primitive.Track
        data-slot="slider-track"
        className="relative grow h-full rounded-full"
      >
        <Primitive.Range
          data-slot="slider-range"
          className="absolute h-full rounded-full"
        />
      </Primitive.Track>
      {values.map((_, index) => (
        <Primitive.Thumb
          key={index}
          data-slot="slider-thumb"
          data-part="thumb"
          aria-label={
            typeof thumbLabel === "function"
              ? thumbLabel(index)
              : (thumbLabel ??
                (values.length > 1 ? `Value ${index + 1}` : undefined))
          }
        />
      ))}
    </Primitive.Root>
  );
}
export type SliderWrapperProps = React.ComponentProps<"div">;
export function SliderWrapper({ className, ...props }: SliderWrapperProps) {
  return (
    <div
      data-slot="slider-wrapper"
      data-part="root"
      className={cn("v-sliderwrap grid gap-3", className)}
      {...props}
    />
  );
}
export type SliderRowProps = React.ComponentProps<"div">;
export function SliderRow({ className, ...props }: SliderRowProps) {
  return (
    <div
      data-slot="slider-row"
      className={cn("v-sliderwrap__row", className)}
      {...props}
    />
  );
}
export type SliderOutputProps = React.ComponentProps<"output">;
export function SliderOutput({ className, ...props }: SliderOutputProps) {
  return (
    <output
      data-slot="slider-output"
      data-part="indicator"
      className={className}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
[data-slot="slider-thumb"] {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--v-ink);
  border: 3px solid var(--v-canvas);
  cursor: pointer;
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]) {
  display: grid;
  gap: 8px;
}
.v-sliderwrap__row:where([data-slot="slider"], [data-slot^="slider-"]) {
  display: flex;
  justify-content: space-between;
  font-size: var(--fs-meta);
  color: var(--muted-foreground);
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]) output {
  font-weight: 600;
  color: var(--v-text);
  font-variant-numeric: tabular-nums;
}
[data-slot="slider-thumb"] {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--v-ink);
  border: 3px solid var(--v-canvas);
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]).-pink {
  background: linear-gradient(
    90deg,
    var(--v-pink) var(--p, 50%),
    var(--v-beige) var(--p, 50%)
  );
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]) {
  box-shadow: none;
  border: 0;
  background: none;
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]),
input[type="range"].v-slider:where(
    [data-slot="slider"],
    [data-slot^="slider-"]
  ) {
  -webkit-appearance: none;
  appearance: none;
  height: 10px;
  border-radius: 999px;
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--v-edge) 40%, transparent);
  border: 0;
  padding: 0;
  margin: 8px 0;
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]).-pink {
  background: linear-gradient(
    90deg,
    var(--v-pink) var(--p, 50%),
    var(--v-beige) var(--p, 50%)
  );
}
[data-slot="slider-thumb"] {
  -webkit-appearance: none;
  appearance: none;
  width: 26px;
  height: 26px;
  margin-top: -8px;
  border: 0;
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  background: var(--v-ink);
  box-shadow: 0 0 0 3px var(--v-canvas);
  cursor: grab;
  transition:
    transform var(--t-micro) var(--enter),
    border-radius var(--t-max) var(--enter);
}
[data-slot="slider-thumb"] {
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  background: var(--v-ink);
  box-shadow: 0 0 0 3px var(--v-canvas);
  cursor: grab;
}
[data-slot="slider"]:hover [data-slot="slider-thumb"] {
  transform: scale(1.08);
  border-radius: 50% 46% 54% 50%/46% 50% 50% 54%;
}
[data-slot="slider"]:active [data-slot="slider-thumb"] {
  transform: scale(1.12, 0.9);
  cursor: grabbing;
  background: var(--v-pink-deep);
}
[data-slot="slider"]:active [data-slot="slider-thumb"] {
  background: var(--v-pink-deep);
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 8px;
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]) {
  gap: 12px;
}
.v-sliderwrap__row:where([data-slot="slider"], [data-slot^="slider-"]) {
  font-size: 14px;
  color: var(--v-text);
  font-weight: 500;
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]) output {
  display: inline-grid;
  place-items: center;
  min-width: 44px;
  height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: var(--v-pink);
  color: var(--v-on-accent);
  font-size: 12.5px;
  font-weight: 600;
}
:root[data-mode="dark"] [data-slot="slider-thumb"] {
  background: var(--v-pink);
  box-shadow: 0 0 0 3px var(--v-canvas);
}
:root[data-mode="dark"] [data-slot="slider-thumb"] {
  background: var(--v-pink);
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]),
input[type="range"].v-slider:where(
    [data-slot="slider"],
    [data-slot^="slider-"]
  ) {
  background: linear-gradient(
    90deg,
    var(--v-pink) var(--p, 0%),
    var(--v-beige) var(--p, 0%)
  );
}
.v-slider:where([data-slot="slider"], [data-slot^="slider-"]).-ink,
input[type="range"].v-slider:where(
    [data-slot="slider"],
    [data-slot^="slider-"]
  ).-ink {
  background: linear-gradient(
    90deg,
    var(--v-ink) var(--p, 0%),
    var(--v-beige) var(--p, 0%)
  );
}
[data-slot="slider-thumb"] {
  cursor: grab;
}
[data-slot="slider"]:active [data-slot="slider-thumb"] {
  cursor: grabbing;
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"]),
.v-sliderwrap__row:where([data-slot="slider"], [data-slot^="slider-"]) {
  box-shadow: none;
  border: 0;
}
.v-sliderwrap:where([data-slot="slider"], [data-slot^="slider-"])
  :is(input[type="range"],[data-slot="slider"]) {
  border: 0;
  box-shadow: none;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="slider"],
  [data-slot^="slider-"],
  [data-slot="slider"]::before,
  [data-slot="slider"]::after,
  [data-slot^="slider-"]::before,
  [data-slot^="slider-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* The native source gradient remains on the host; multiple values use Radix range geometry. */
[data-slot="slider"][data-range].v-slider {
  background: var(--v-beige);
}
[data-slot="slider-range"] {
  background: transparent;
}
[data-slot="slider"][data-range] [data-slot="slider-range"] {
  background: var(--v-pink);
}
[data-slot="slider"][data-range].-ink [data-slot="slider-range"] {
  background: var(--v-ink);
}
[data-slot="slider-thumb"] {
  display: block;
  margin-top: 0;
}
[data-slot="slider-thumb"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 8px;
}
[data-slot="slider"][data-orientation="vertical"] {
  width: 10px;
  height: var(--h, 200px);
  flex-direction: column;
}
[data-slot="slider"][data-orientation="vertical"] [data-slot="slider-track"] {
  width: 100%;
  height: 100%;
}
[data-slot="slider"][data-orientation="vertical"] [data-slot="slider-range"] {
  width: 100%;
  height: auto;
}
[data-slot="slider"][data-disabled],
[data-slot="slider"][data-disabled] [data-slot="slider-thumb"] {
  cursor: not-allowed;
}
[data-slot="slider"][data-disabled] [data-slot="slider-thumb"] {
  background: var(--v-disabled-fill);
}

}
